  ('ssc-cgl-general-awareness-physics-gk-q08', 'ssc-cgl-general-awareness-physics-gk', 'The instrument used to measure temperature is the:', 'Thermometer', 'Barometer', 'Ammeter', 'Voltmeter', 'A', 'A thermometer measures temperature.', 7),
  ('ssc-cgl-general-awareness-physics-gk-q08b', 'ssc-cgl-general-awareness-physics-gk', 'Sound cannot travel through a:', 'Vacuum', 'Solid', 'Liquid', 'Gas', 'A', 'Sound needs a medium; it cannot travel through a vacuum.', 8),
