  ('gate-core-cs-computer-networks-q13', 'gate-core-cs-computer-networks', 'How many layers does the OSI model have?', '7', '4', '5', '3', 'A', 'The OSI reference model has 7 layers; TCP/IP has 4.', 12),
  ('gate-core-cs-computer-networks-q14', 'gate-core-cs-computer-networks', 'Which protocol is connection-oriented and reliable?', 'TCP', 'UDP', 'IP', 'ICMP', 'A', 'TCP is reliable and connection-oriented; UDP is neither.', 13),
  ('gate-core-cs-computer-networks-q15', 'gate-core-cs-computer-networks', 'How many usable host addresses does a /24 subnet provide?', '254', '256', '252', '128', 'A', '2^(32−24) − 2 = 256 − 2 = 254 usable hosts.', 14),
  ('gate-core-cs-computer-networks-q16', 'gate-core-cs-computer-networks', 'Which protocol resolves an IP address to a MAC address?', 'ARP', 'DNS', 'DHCP', 'ICMP', 'A', 'ARP maps IP addresses to MAC (link-layer) addresses.', 15),
  ('gate-core-cs-theory-of-computation-q13', 'gate-core-cs-theory-of-computation', 'A DFA and an NFA recognise:', 'Exactly the same class of languages', 'Different classes', 'Context-free languages', 'Recursive languages only', 'A', 'Every NFA has an equivalent DFA, so both accept the regular languages.', 12),
